from typing import List

class Solution:
    def subsetsWithDup(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        result = []
        self.helper(0, nums, [], result)
        return result

    def helper(self, i, nums, curr, output):
        output.append(curr[:])
        for j in range(i, len(nums)):
            if j > i and nums[j] == nums[j-1]:
                continue
            curr.append(nums[j])
            self.helper(j+1, nums, curr, output)
            curr.pop()

class Solution:
    def getAllMax(self, s, startIndex):
        if len(s[startIndex::]) == 0:
            return []
        maxEl = max(s[startIndex::])
        if maxEl == s[startIndex]:
            return []
        res = []
        for i in range(startIndex, len(s)):
            if s[i] == maxEl:
                res.append(i)
        return res

    def swap(self, slist, i, j):
        temp = slist[i]
        slist[i] = slist[j]
        slist[j] = temp
    def findMaximumNum(self, s, k):
        slist = list(s)
        maxNum = float('-inf')
        maxNum = self._findMaximumNum(slist, 0, k, maxNum)
        return str(maxNum)

    def _findMaximumNum(self, s, i, k, maxNum):
        print(s)
        if k <= 0 or i >= len(s):
            return int(''.join(s))
        choices = self.getAllMax(s, i)
        print('choices', choices)
        if len(choices) == 0:
            maxNum = max(self._findMaximumNum(s,i+1,k, maxNum), maxNum)
        for choice in choices:
            self.swap(s, i, choice)
            maxNum = max(self._findMaximumNum(s,i+1,k-1, maxNum), maxNum)
            self.swap(s, choice, i)

        return maxNum


