def lcs_length(s1: str, s2: str, i: int, j: int, dp) -> str :
    if i == 0 or j == 0:
        return 0
    if dp[i][j] != -1:
        return dp[i][j]

    if s1[i-1] == s2[j-1]:
        dp[i][j] = 1 + lcs_length(i-1, j-1)
    else:
        dp[i][j] = max(lcs_length(i-1, j), lcs_length(i, j-1))
    return dp[i][j]


